export const MODIFIER_RECORDS = [{"label": "Backlit Silhouette", "axis": "lighting", "detail": "shot into the light: the subject collapsing into a dark shape against a glowing background, a bright halo tracing the outline and haze blooming across the frame.", "aliases": ["contre-jour", "into the light", "shape only"]}, {"label": "Bioluminescent Glow", "axis": "lighting", "detail": "lit from within by bioluminescence: a cold blue-green glow emitted by the forms themselves, falling off fast into deep indigo darkness, soft haloes around every emitting edge and a faint teal bounce landing on whatever sits nearby.", "aliases": ["living light", "foxfire", "biolume"]}, {"label": "Blue Hour", "axis": "lighting", "detail": "caught at blue hour: the sky an even deep blue with the sun already gone, warm artificial lights starting to take over and windows glowing against the dusk.", "aliases": ["twilight", "dusk", "after sunset"]}, {"label": "Candlelight", "axis": "lighting", "detail": "lit by candlelight: a small warm flame close in, falling off fast into surrounding dark, amber light on skin and a point of flame caught in the eyes.", "aliases": ["firelight", "flame lit", "warm low light"]}, {"label": "Chiaroscuro", "axis": "lighting", "detail": "lit with chiaroscuro: a single strong keylight carves the subject out of near-black shadow, the form reading through extreme contrast with large areas falling away into the dark ground.", "aliases": ["dramatic light", "Rembrandt lighting"]}, {"label": "Dappled Shade", "axis": "lighting", "detail": "lit through dappled shade: scattered pools of warm sun breaking across the form, cool shade filling the spaces between, the shadow pattern mottled and organic rather than drawn.", "aliases": ["leaf shadow", "sun through leaves", "broken light"]}, {"label": "Direct Flash", "axis": "lighting", "detail": "lit by direct on-camera flash: a hard frontal burst flattening the form, hot speculars on whatever is nearest, a hard-edged shadow thrown just behind and everything beyond it dropping into black.", "aliases": ["on-camera flash", "snapshot flash", "harsh flash"]}, {"label": "Firelight", "axis": "lighting", "detail": "lit by firelight: a warm orange key rising from below and flickering unevenly, hot amber catching every upward-facing plane while tall soft shadows leap behind, the glow dropping away fast into deep brown darkness through a faint haze of smoke.", "aliases": ["campfire light", "hearth glow", "torchlight"]}, {"label": "Fluorescent Overhead", "axis": "lighting", "detail": "lit by overhead fluorescent tubes: a flat green-cyan cast across everything, short hard shadows dropped straight down leaving dark hollows beneath the brows, the rest filled evenly and shadowlessly at a slightly sickly colour balance.", "aliases": ["strip light", "office lighting", "institutional light"]}, {"label": "God Rays", "axis": "lighting", "detail": "lit by god rays: distinct shafts cutting through the haze from a high source behind, dust turning in the beams, bright wedges of light standing against the deep shade around them.", "aliases": ["crepuscular rays", "light shafts", "volumetric beams"]}, {"label": "Golden Hour", "axis": "lighting", "detail": "lit by golden-hour sunlight falling low from the side - long crisp shadows, rim-lit edges glowing amber-orange against softened warm highlights, the whole scene wrapped in the last deep light of the afternoon.", "aliases": ["sunset light", "warm sidelight"]}, {"label": "Hard Noon Sun", "axis": "lighting", "detail": "under a hard noon sun: light falling straight down into short black shadows, highlights blown to white, the whole scene bleached and squinting.", "aliases": ["harsh midday", "overhead sun", "high sun"]}, {"label": "High-Key", "axis": "lighting", "detail": "lit high-key: light arriving from several directions at once so the shadows lift almost to white, the background going pale and luminous and the whole frame reading bright, clean and airy.", "aliases": ["bright even", "airy light", "low contrast bright"]}, {"label": "Moonlight", "axis": "lighting", "detail": "lit by moonlight: a cool blue-silver key from high above, everything else sinking into deep blue shadow, only the upper edges catching a faint rim.", "aliases": ["night light", "lunar", "blue night"]}, {"label": "Neon Noir", "axis": "lighting", "detail": "bathed in neon: coloured gels split the scene into magenta and cyan, volumetric fog catches every beam, wet reflective surfaces mirror the glow in sharp streaks, and deep shadows swallow everything the light leaves alone.", "aliases": ["cyberpunk lighting", "neon street"]}, {"label": "Overcast Soft", "axis": "lighting", "detail": "lit by flat overcast daylight: the whole sky acting as one soft diffuser, shadows barely present, every surface evenly revealed every edge softly graduated.", "aliases": ["cloudy", "diffuse daylight", "soft box sky"]}, {"label": "Practical Glow", "axis": "lighting", "detail": "lit by what is in the room: table lamps, signs and screens pooling warm light unevenly, the sources themselves visible in frame.", "aliases": ["lamp light", "in-scene light", "motivated light"]}, {"label": "Rim Lighting", "axis": "lighting", "detail": "rim-lit: a strong backlight traces every contour in a bright white edge against a dark ground, the subject solid and readable through outline alone, with a faint hazy bloom where the light wraps around the form.", "aliases": ["backlight", "edge light"]}, {"label": "Split Lighting", "axis": "lighting", "detail": "split lit: the key placed square to the side so one half is fully lit and the other falls away into shadow, a hard division running down the centre.", "aliases": ["side light", "half lit", "ninety degree key"]}, {"label": "Stage Spotlight", "axis": "lighting", "detail": "lit by a hard theatrical spotlight: one bright pool of light with a sharply defined edge, everything beyond it falling to black, the beam visible as a cone through haze and carving deep shadow from a strong top-front angle.", "aliases": ["followspot", "theatrical spot", "hard pool of light"]}, {"label": "Studio Softbox", "axis": "lighting", "detail": "lit with a large studio softbox: a soft controlled key just off axis, gentle falloff across the form, a clean catchlight and every shadow controlled and intentional.", "aliases": ["studio strobe", "beauty light", "controlled light"]}, {"label": "Underwater Caustics", "axis": "lighting", "detail": "lit through water: rippling nets of caustic light dancing across every surface, colour draining toward blue-green with depth and particles drifting through the shafts.", "aliases": ["caustics", "pool light", "submerged"]}, {"label": "Black & White", "axis": "color_grade", "detail": "rendered in black and white: the full tonal range from bright high-key whites to deep blacks, every surface read through luminance alone with luminance values alone throughout the image.", "aliases": ["bw", "monochrome", "grayscale"]}, {"label": "Bleach Bypass", "axis": "color_grade", "detail": "graded like a bleach bypass: colour drained almost out while contrast climbs, highlights going silvery and the whole frame taking a hard grey-green cast.", "aliases": ["silver retention", "desaturated contrast"]}, {"label": "Cool Blue", "axis": "color_grade", "detail": "graded cold: a blue-grey cast across everything, warmth pulled out of the highlights, the whole frame reading wintry and detached.", "aliases": ["cold grade", "blue cast"]}, {"label": "Cross-Process", "axis": "color_grade", "detail": "cross-processed: shadows swinging cyan and highlights toward yellow-green, contrast blown out and every hue rotated somewhere it should not be.", "aliases": ["c41 in e6", "shifted colour"]}, {"label": "Duotone", "axis": "color_grade", "detail": "graded as a duotone: shadows tinted one hue, highlights another, the midtones a stark graphic transition between the two, posterised into flat colour bands.", "aliases": ["two-tone", "split tone"]}, {"label": "Faded Film", "axis": "color_grade", "detail": "graded like a faded print: blacks lifted milky, an age cast creeping through the midtones and contrast worn down as though it sat too long in the light.", "aliases": ["washed out", "sun faded", "aged print"]}, {"label": "High Saturation", "axis": "color_grade", "detail": "graded loud: every hue pushed to the edge of clipping, contrast punched up, the colour doing as much work as the composition.", "aliases": ["vivid", "punchy colour"]}, {"label": "Kodachrome", "axis": "color_grade", "detail": "graded like Kodachrome: reds sitting dense and saturated, blues held cool and restrained, blacks staying deep with very little lift, and a fine tight grain running through the whole frame.", "aliases": ["Kodachrome film", "slide film colour", "K-14"]}, {"label": "Monochrome Green", "axis": "color_grade", "detail": "graded to a single green hue: every tone reduced to a shade of phosphor green, highlights blooming outward, noise crawling through the shadows and the darkest areas dropping away to black.", "aliases": ["night vision", "phosphor green", "image intensifier"]}, {"label": "Muted Earth", "axis": "color_grade", "detail": "graded to muted earth: ochre, umber and olive holding the frame, saturation kept in check so nothing shouts.", "aliases": ["earth tones", "desaturated natural"]}, {"label": "Pastel Wash", "axis": "color_grade", "detail": "graded into pastel: blacks lifted to soft grey, the palette drifting through pale pink and mint and butter yellow with contrast kept deliberately gentle.", "aliases": ["soft palette", "muted pastel"]}, {"label": "Selective Colour", "axis": "color_grade", "detail": "graded as selective colour: one hue kept at full saturation while everything around it falls to neutral grey, so the kept colour reads first and the rest sits back as plain tone.", "aliases": ["spot colour", "colour isolation", "one hue kept"]}, {"label": "Sepia", "axis": "color_grade", "detail": "toned in sepia: warm browns replace the grayscale, cream-coloured highlights bleeding into chocolate shadows, the whole image carrying the faded warmth of an old photograph.", "aliases": ["vintage photo", "brown tone"]}, {"label": "Split Tone", "axis": "color_grade", "detail": "split toned: one hue settling into the shadows and its opposite into the highlights, the midtones left near neutral between them.", "aliases": ["split toning", "two-tone grade"]}, {"label": "Teal & Orange", "axis": "color_grade", "detail": "graded teal and orange: shadows pushed toward cyan while skin holds a warm orange, the two pulling apart into hard complementary separation.", "aliases": ["blockbuster grade", "complementary grade"]}, {"label": "Warm Amber", "axis": "color_grade", "detail": "graded warm: honey in the highlights and gold through the midtones, even the shadows staying brown rather than turning blue.", "aliases": ["golden grade", "amber cast"]}, {"label": "Ancient Classical", "axis": "era", "detail": "set in classical antiquity: draped linen against marble and bronze, fluted columns and terracotta under a hard Mediterranean sun.", "aliases": ["antiquity", "greco-roman", "classical world"]}, {"label": "Medieval", "axis": "era", "detail": "set in the medieval world: rough wool and leather, hand-forged iron, timber and lime-washed stone lit by hearth and candle in muted vegetable dyes.", "aliases": ["middle ages", "mediaeval"]}, {"label": "Renaissance", "axis": "era", "detail": "set in the Renaissance: slashed doublets and structured brocade, braided hair under a jewelled caul, carved walnut and coffered detailing in ochre, crimson and deep green under warm window light.", "aliases": ["15th century", "16th century", "cinquecento"]}, {"label": "Baroque (17th Century)", "axis": "era", "detail": "set in the seventeenth century: wide lace collars and long curled wigs above heavy dark silk shot with silver, turned oak and pewter among weighty drapery, the palette umber, oxblood and black against sharp white linen under a single candle.", "aliases": ["seventeenth century", "1600s", "cavalier period"]}, {"label": "Georgian (18th Century)", "axis": "era", "detail": "set in the eighteenth century: powdered wigs above embroidered frock coats and wide panniered gowns, gilded plasterwork and inlaid mahogany around them, the palette powder blue, shell pink and cream picked out in gold under soft candlelight.", "aliases": ["eighteenth century", "1700s", "rococo period"]}, {"label": "Victorian", "axis": "era", "detail": "dressed in Victorian sensibility: gaslight casting a warm amber glow over dark wood and brass, ornate filigree and etched glass catching the light, velvet drapes and oil-lamp ambiance softening every surface into the deep warmth of the 19th century.", "aliases": ["19th century", "gaslight"]}, {"label": "Edwardian", "axis": "era", "detail": "set in the Edwardian moment: high collars and long unbroken lines, pale linen and lace, wicker and painted iron under a soft garden light.", "aliases": ["belle epoque", "1900s", "turn of the century"]}, {"label": "1910s", "axis": "era", "detail": "set in the 1910s: high-waisted narrow tunic dresses under wide plumed hats, stiff collars and heavy three-piece wool, the tailoring turning plain and utilitarian in dark serge, taupe and dusty rose under early tungsten bulbs mixed with gaslight.", "aliases": ["nineteen-tens", "wartime period", "pre-jazz age"]}, {"label": "1920s", "axis": "era", "detail": "set in the 1920s: art deco geometry in every fitting, drop-waist silhouettes and cloche hats, brass and black lacquer catching the light of a smoky room.", "aliases": ["twenties", "jazz age", "art deco era"]}, {"label": "1930s-40s", "axis": "era", "detail": "set in the 1930s and 40s: wide-shouldered tailoring over bias-cut drape, wool and rayon in utility colours, streamlined bakelite and chrome fittings under warm tungsten light.", "aliases": ["thirties", "forties", "wartime", "depression era"]}, {"label": "1950s", "axis": "era", "detail": "set in the 1950s: full skirts and sharp tailoring, chrome and formica surfaces in pastel, everything carrying the confident gloss of the atomic age.", "aliases": ["fifties", "mid-century", "atomic age"]}, {"label": "1960s", "axis": "era", "detail": "set in the 1960s: mod geometry and op-art contrast, space-age plastic forms and bold primary blocking cut into sharp graphic shapes.", "aliases": ["sixties", "mod", "space age"]}, {"label": "1970s", "axis": "era", "detail": "steeped in 1970s aesthetic: warm orange-brown earth tones, soft film grain, the slight soft-focus bloom of the era's lenses, avocado green and harvest gold accents grounding the image in the decade.", "aliases": ["70s", "seventies"]}, {"label": "1980s", "axis": "era", "detail": "pure 1980s: neon pinks and electric blues against chrome and black glass, bold geometric grids, high-contrast lighting with coloured gels, the graphic confidence of the decade in every surface.", "aliases": ["80s", "eighties", "retrowave"]}, {"label": "1990s", "axis": "era", "detail": "set in the 1990s: grainy consumer film, flannel and sportswear, beige monitors humming in the corner and the hard flat pop of a disposable flash.", "aliases": ["nineties", "grunge era"]}, {"label": "2000s", "axis": "era", "detail": "set in the early 2000s: frosted translucent plastic and chrome on every object, the slightly soft look of an early digital sensor, metallic blue running through it all.", "aliases": ["y2k", "noughties", "early digital"]}, {"label": "2010s", "axis": "era", "detail": "set in the 2010s: matte anodised metal and edge-to-edge glass, flat single-colour interface design, exposed bulbs over reclaimed timber and a hazy warm filter across the whole frame.", "aliases": ["twenty-tens", "smartphone era", "millennial"]}, {"label": "2020s", "axis": "era", "detail": "set in the 2020s: oversized relaxed shapes in muted sage and terracotta, soft rounded forms in bouclé and matte ceramic, blurred translucent interface panels and the even flat wash of a ring light.", "aliases": ["twenty-twenties", "early 2020s", "post-2020"]}, {"label": "Near Future", "axis": "era", "detail": "set slightly ahead of now: matte composite surfaces with joins hidden, soft displays embedded where panels used to be, a muted palette broken by one signal colour.", "aliases": ["plausible future", "next decade"]}, {"label": "Far Future", "axis": "era", "detail": "set far ahead: materials with seamless joins and structures that look grown rather than built, light arriving with an unexplained source.", "aliases": ["distant future", "post-technological"]}, {"label": "Barrel / Fisheye Distortion", "axis": "finish", "detail": "finished with heavy barrel distortion: straight lines bowing outward as they approach the frame edge, the centre swelling forward and enlarging while the corners compress and darken across an exaggerated curvilinear field.", "aliases": ["fisheye", "wide-angle distortion", "curvilinear lens"]}, {"label": "Bloom / Glow", "axis": "finish", "detail": "finished with a soft bloom: bright areas spill a diffused glow across adjacent edges, highlights bleeding into the shadows with a dreamy haze, blacks lifted into a gentle grey so nothing bites into pure darkness.", "aliases": ["soft glow", "haze", "diffusion"]}, {"label": "Blown Highlights", "axis": "finish", "detail": "finished overexposed: the highlights clipped flat to paper white with the detail gone out of them entirely, halation bleeding at their edges and the midtones washed bright behind.", "aliases": ["overexposed", "clipped whites", "hot exposure"]}, {"label": "Chromatic Aberration", "axis": "finish", "detail": "finished with visible chromatic aberration: red and cyan fringes creeping wider toward the corners and a purple edge wherever contrast is hardest.", "aliases": ["colour fringing", "lens fringe"]}, {"label": "Crushed Blacks", "axis": "finish", "detail": "finished with crushed blacks: the dark tones clipped flat to pure black with nothing recoverable inside them, a hard edge where the falloff meets the void, the form emerging out of solid dark.", "aliases": ["underexposed", "clipped shadows", "deep blacks"]}, {"label": "Distressed & Damaged", "axis": "finish", "detail": "finished as something handled too much: scratches and dust across the surface, emulsion scarred, edges torn and old fold marks still showing.", "aliases": ["scratched", "worn", "damaged emulsion"]}, {"label": "Dithered", "axis": "finish", "detail": "finished with ordered dithering: tone faked by patterned clusters of pixels against a tiny palette, the grid plainly visible.", "aliases": ["ordered dither", "bayer", "1-bit"]}, {"label": "Film Grain", "axis": "finish", "detail": "finished with heavy 35mm film grain: a visible particulate texture across the whole image, subtle colour shifts dancing in the grain, the slight softness and warmth of celluloid at the edges.", "aliases": ["grainy", "35mm", "analog"]}, {"label": "Glossy Lacquer", "axis": "finish", "detail": "finished under gloss lacquer: specular highlights sharp as mirrors, blacks looking permanently wet and the surroundings reflected across the surface.", "aliases": ["high gloss", "varnish", "wet look"]}, {"label": "Halftone Dots", "axis": "finish", "detail": "finished as a halftone: every tone built from visible dots of varying size, the rosette pattern showing plainly and ink spreading a little at each edge.", "aliases": ["ben-day", "dot screen", "print dots"]}, {"label": "JPEG Artifacts", "axis": "finish", "detail": "finished with heavy JPEG compression: square block structure surfacing across the flat areas, ringing haloes clinging to hard edges, colour smearing past its boundaries and gradients breaking into visible bands.", "aliases": ["compression artifacts", "blocking", "lossy compression"]}, {"label": "Lens Flare", "axis": "finish", "detail": "finished with lens flare: a chain of polygonal ghosts stepping across the frame from the brightest point, a horizontal streak drawn through it and veiling glare washing the contrast out of one corner.", "aliases": ["flare", "ghosting", "anamorphic streak"]}, {"label": "Matte Flat", "axis": "finish", "detail": "finished dead matte: a uniformly diffuse surface, the surface absorbing light into a chalky uniform diffusion and the blacks going velvety.", "aliases": ["chalky", "no sheen", "dead matte"]}, {"label": "Motion Blur", "axis": "finish", "detail": "finished with directional motion blur: form smeared along its own path of travel, edges drawn out into streaks and trailing contours, with sharpness surviving only where the movement paused.", "aliases": ["long shutter", "movement smear", "panning blur"]}, {"label": "Oversharpened Halo", "axis": "finish", "detail": "finished heavily over-sharpened: a bright halo outlining every high-contrast edge, micro-contrast exaggerated until texture crawls, fine detail hardened to a brittle crunch and grain standing up across the flat areas.", "aliases": ["over-sharpening", "unsharp mask halo", "crunchy detail"]}, {"label": "Paper Texture", "axis": "finish", "detail": "finished on heavy textured paper: the tooth of the stock breaking every mark, fibres catching pigment unevenly and the sheet cockling slightly.", "aliases": ["tooth", "rag paper", "textured stock"]}, {"label": "Posterized", "axis": "finish", "detail": "finished posterised: tone collapsed into a few flat bands with hard edges between them and every level a single flat step.", "aliases": ["banded", "reduced levels", "flat bands"]}, {"label": "Scan Lines", "axis": "finish", "detail": "finished like a CRT: horizontal scan lines across everything, phosphor glow blooming from the bright areas and a faint colour fringe at the edges.", "aliases": ["crt", "video lines", "interlaced"]}, {"label": "Shallow Depth of Field", "axis": "finish", "detail": "finished with a shallow depth of field: one narrow plane held critically sharp while everything before and behind it dissolves, speculars swelling into soft round discs across the far tones.", "aliases": ["bokeh", "wide aperture", "selective focus"]}, {"label": "Soft Diffusion", "axis": "finish", "detail": "finished through a diffusion filter: highlights blooming gently outward and contrast easing, detail still present beneath a soft veil.", "aliases": ["mist filter", "pro-mist", "glow diffusion"]}, {"label": "Vignette", "axis": "finish", "detail": "framed by a strong vignette: the edges fall off into deep black, drawing the eye to the centre in a gradual luminance tunnel - the subject spotlit by the frame itself.", "aliases": ["darkened edges", "spotlight falloff"]}, {"label": "Awe", "axis": "mood", "detail": "the mood is awe: scale overwhelming the frame, the subject small beneath something vast, light arriving from somewhere past the edge.", "aliases": ["sublime", "vast", "overwhelming"]}, {"label": "Chaotic", "axis": "mood", "detail": "the mood is chaotic: focal points fighting each other, colours clashing and lines tilting until there is every path through the frame contested.", "aliases": ["frantic", "disordered", "overwhelming"]}, {"label": "Cozy", "axis": "mood", "detail": "a cozy mood: warm light pooling in an enclosed space, soft woollen texture and rounded forms in amber, honey and cream, everything unhurried, sheltered and quietly content.", "aliases": ["hygge", "snug", "comforting"]}, {"label": "Deadpan", "axis": "mood", "detail": "a deadpan mood: something odd presented completely straight, lit evenly with nothing emphasised, arranged symmetrically and matter-of-factly in muted plain colour, the absurdity left entirely unremarked.", "aliases": ["straight-faced", "dry", "affectless"]}, {"label": "Dreamlike", "axis": "mood", "detail": "the mood is dreamlike: edges dissolving where they should hold, light arriving from an unseen source, scale not quite right and nothing firmly on the ground.", "aliases": ["oneiric", "surreal calm", "unreal"]}, {"label": "Heroic", "axis": "mood", "detail": "the mood is heroic: the camera low and looking up, a strong rim light separating the form from a bright sky, wind lifting everything loose and the composition holding the figure dead centre.", "aliases": ["triumphant", "epic", "noble"]}, {"label": "Hopeful", "axis": "mood", "detail": "a hopeful mood: cool darkness giving way to warm light rising along one edge, the composition lifting upward into open air, the palette pale gold and soft blue and clean, everything poised at a beginning.", "aliases": ["optimistic", "uplifting", "dawning"]}, {"label": "Intimate", "axis": "mood", "detail": "the mood is intimate: framed close and focused shallow, warm low light on skin, the space enclosed and nothing else asking for attention.", "aliases": ["close", "tender", "private"]}, {"label": "Joyful", "axis": "mood", "detail": "the mood is joyful: bright open light and a warm saturated palette, the composition lifting upward and everything held loose and unguarded.", "aliases": ["happy", "celebratory", "buoyant"]}, {"label": "Lonely", "axis": "mood", "detail": "the mood is lonely: one figure adrift in a space far too large, negative space opening up on every side and the figure entirely alone in the frame.", "aliases": ["isolated", "solitary", "empty"]}, {"label": "Melancholic", "axis": "mood", "detail": "the mood is melancholic: desaturated cool tones under an overcast light, a quiet stillness in the composition, the whole scene holding its breath in blue-grey silence.", "aliases": ["somber", "wistful", "blue mood"]}, {"label": "Mysterious", "axis": "mood", "detail": "the mood is mysterious: the form half-withheld by shadow and haze, one light source explaining a little and leaving the rest unaccounted for, detail dissolving as it recedes.", "aliases": ["enigmatic", "obscured", "withholding"]}, {"label": "Nostalgic", "axis": "mood", "detail": "the mood is nostalgic: a warm faded palette and soft edges, light coming through dust or curtains onto things visibly worn by use.", "aliases": ["wistful", "remembered", "bittersweet"]}, {"label": "Oppressive", "axis": "mood", "detail": "the mood is oppressive: forms crowding inward and weight gathering at the top of the frame, the palette going murky and headroom almost gone.", "aliases": ["heavy", "claustrophobic", "weighted"]}, {"label": "Reverent", "axis": "mood", "detail": "the mood is reverent: light falling from high above onto a still symmetrical arrangement, space left open overhead, the palette muted to stone and gold and everything holding quiet.", "aliases": ["solemn", "sacred", "devotional"]}, {"label": "Romantic", "axis": "mood", "detail": "the mood is romantic: a warm rose-gold light blooming in the highlights, focus falling gently away at the edges, everything held close and rendered forgiving.", "aliases": ["tender", "amorous", "swooning"]}, {"label": "Serene", "axis": "mood", "detail": "the mood is serene: soft diffused light falling evenly across a pastel palette, the composition balanced and still, a gentle quiet calm that asks nothing of the viewer.", "aliases": ["peaceful", "calm", "tranquil"]}, {"label": "Sinister", "axis": "mood", "detail": "the mood is sinister: low-key lighting barely revealing forms, unsettling cold colour temperature, deep shadows swallowing detail at the edges, a slight dutch tilt making everything feel slightly wrong.", "aliases": ["ominous", "unsettling", "dark"]}, {"label": "Tense", "axis": "mood", "detail": "the mood is tense: the frame closing in, shadows hardening at their edges and the subject pressed toward the border in a held-breath stillness.", "aliases": ["anxious", "suspenseful", "on edge"]}, {"label": "Uncanny", "axis": "mood", "detail": "an uncanny mood: everything nearly correct and subtly wrong, proportions a little off and the symmetry too exact, the light flat and even while the shadows disagree with it, surfaces waxy and colour a half-step from natural.", "aliases": ["unheimlich", "almost-right", "wrongness"]}, {"label": "Whimsical", "axis": "mood", "detail": "the mood is whimsical: scale playing tricks, lines bouncing rather than running straight, mismatched cheerful colour and an absurdity nobody in frame finds odd.", "aliases": ["playful", "charming", "light-hearted"]}];

